using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Interactivity;
using Avalonia.Threading;
using Avalonia.VisualTree;
using System.Net;
using System.Text;
using System.Text.Json;
namespace ProjectDesk;

public static class McpValidation {
 public static int Run(string output){Directory.CreateDirectory(output);var checks=new List<string>();void Assert(bool value,string message){if(!value)throw new Exception(message);checks.Add(message);}
  Task.Run(async()=>{
   var secrets=new McpCredentialStore();var demo=McpConnectorsWindow.DemoDefinition();var store=new McpSettingsStore(Path.Combine(output,"connectors-"+Guid.NewGuid()+".json"));store.Servers.Add(demo);store.Save();Assert(new McpSettingsStore(store.Path).Servers.Single().Address==demo.Address,"Server setup reloads");
   string secret="validation-only-"+Guid.NewGuid();try{secrets.Write(demo.Id,"Bearer",secret);Assert(secrets.Read(demo.Id,"Bearer")==secret,"Windows credential roundtrip");Assert(!File.ReadAllText(store.Path).Contains(secret),"Credentials excluded from setup JSON");}finally{secrets.Remove(demo.Id,"Bearer");}Assert(secrets.Read(demo.Id,"Bearer")==null,"Test credential removed");
   using var session=new ProjectSession();var revision=new McpProjectRevision();Assert(revision.Current(session)==revision.Current(session),"Empty project revision is stable");session.NewProject("Connector validation",new DateTime(2026,10,19,8,0,0));var originalRevision=revision.Current(session);var gate=new McpInvocationGate();
   foreach(var protocol in new string?[]{null,"2025-11-25"}){
    await using var connection=new McpConnection(demo with{ProtocolVersion=protocol},secrets);using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(25));await connection.ConnectAsync(timeout.Token);Assert(connection.Connected&&connection.Tools.Count==2,"Stdio discovery "+(protocol??"Auto"));Assert(session.Tasks.Count==0,"Discovery leaves project unchanged");
    McpToolProposal Proposal(string tool,string json)=>new(demo.Id,tool,json,connection.ReviewRevision(revision.Current(session)),false,true);
    var proposal=Proposal("echo","{\"message\":\"validation\"}");bool denied=false;try{await connection.InvokeAsync(proposal,Guid.NewGuid(),gate,()=>revision.Current(session),timeout.Token);}catch(InvalidOperationException){denied=true;}Assert(denied,"Unreviewed invocation rejected "+protocol);
    var result=await connection.InvokeAsync(proposal,gate.Approve(proposal),gate,()=>revision.Current(session),timeout.Token);using var parsed=JsonDocument.Parse(result);Assert(parsed.RootElement.GetProperty("structuredContent").GetProperty("message").GetString()=="validation","Reviewed stdio call "+protocol);int child=parsed.RootElement.GetProperty("structuredContent").GetProperty("processId").GetInt32();
    var tasks=Proposal("example_tasks","{}");var approval=gate.Approve(tasks);string imported=await connection.InvokeAsync(tasks,approval,gate,()=>revision.Current(session),timeout.Token);Assert(session.Tasks.Count==0,"Result never mutates the project automatically");denied=false;try{await connection.InvokeAsync(tasks,approval,gate,()=>revision.Current(session),timeout.Token);}catch(InvalidOperationException){denied=true;}Assert(denied,"Approval cannot be reused");
    var rows=McpTaskImport.Parse(imported);Assert(rows.Count==3,"Structured task result parsed");McpTaskImport.Apply(session,[rows[0],rows[2]]);Assert(session.Tasks.Count==2&&session.Tasks.All(t=>t.Start.HasValue&&t.Finish.HasValue),"Selected tasks import with automatic dates");Assert(revision.Current(session)!=originalRevision,"Import invalidates reviewed project revision");var stale=gate.Approve(tasks);denied=false;try{await connection.InvokeAsync(tasks,stale,gate,()=>revision.Current(session),timeout.Token);}catch(InvalidOperationException){denied=true;}Assert(denied,"Stale project approval rejected");session.Undo();Assert(session.Tasks.Count==0,"Single Undo removes imported tasks");Assert(revision.Current(session)!=originalRevision,"Undo cannot restore an old review token");
    await connection.DisposeAsync();await Task.Delay(200);bool exited;try{using var process=System.Diagnostics.Process.GetProcessById(child);exited=process.HasExited;}catch(ArgumentException){exited=true;}Assert(exited,"Disconnect stops only owned demo child "+protocol);
   }
   string marker=Path.GetFullPath(Path.Combine(output,"owned-stall & %literal%.txt"));await using(var stalled=new McpConnection(demo with{Arguments=Program.SelfCommand("--mcp-stall-fixture",marker).Arguments,ProtocolVersion="2025-11-25"},secrets)){using var cancelConnect=new CancellationTokenSource(TimeSpan.FromSeconds(2));bool cancelled=false;try{await stalled.ConnectAsync(cancelConnect.Token);}catch(OperationCanceledException){cancelled=true;}Assert(cancelled&&!stalled.Connected,"Stalled handshake cancels cleanly");Assert(File.Exists(marker),"Owned stalled fixture started");int pid=int.Parse(File.ReadAllText(marker));await Task.Delay(200);bool gone;try{using var process=System.Diagnostics.Process.GetProcessById(pid);gone=process.HasExited;}catch(ArgumentException){gone=true;}Assert(gone,"Canceled handshake does not leave an owned child behind");}
   using var handler=new FixtureHttp();using var http=new HttpClient(handler);var remote=new McpServerDefinition(Guid.NewGuid().ToString(),"HTTP fixture",McpConnectorTransport.RemoteHttps,"https://fixture.invalid/mcp",[],Authentication:McpAuthentication.BearerToken,ProtocolVersion:"2025-11-25");try{secrets.Write(remote.Id,"Bearer","fixture-token");await using var connection=new McpConnection(remote,secrets);using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(15));await connection.ConnectAsync(timeout.Token,http);Assert(connection.Tools.Count==1&&handler.Authorized,"HTTPS transport sends configured bearer and discovers tools");var p=new McpToolProposal(remote.Id,"echo","{\"message\":\"hello\"}",connection.ReviewRevision(revision.Current(session)),false,true);var response=await connection.InvokeAsync(p,gate.Approve(p),gate,()=>revision.Current(session),timeout.Token);Assert(response.Contains("fixture result"),"HTTP reviewed tool call");handler.Slow=true;using var cancel=new CancellationTokenSource(100);bool canceled=false;try{await connection.RefreshToolsAsync(cancel.Token);}catch(OperationCanceledException){canceled=true;}Assert(canceled,"HTTP request cancellation");}finally{secrets.Remove(remote.Id,"Bearer");}
   bool bad=false;try{McpArgumentValidator.Validate("{}",JsonSerializer.SerializeToElement(new{type="object",required=new[]{"message"}}));}catch(ArgumentException){bad=true;}Assert(bad,"Missing required arguments rejected");bad=false;try{McpTaskImport.Parse("{\"structuredContent\":{\"tasks\":[{\"name\":\"A\",\"percentComplete\":101}]}}");}catch(ArgumentException){bad=true;}Assert(bad&&session.Tasks.Count==0,"Invalid task result leaves project unchanged");bad=false;try{McpBrowserLogin.ParseQuery("?code=x&state=a&state=b");}catch(ArgumentException){bad=true;}Assert(bad,"Duplicate OAuth callback state rejected");
  }).GetAwaiter().GetResult();
  AppBuilder.Configure<DesktopApp>().UseSkia().UseHeadless(new AvaloniaHeadlessPlatformOptions{UseHeadlessDrawing=false}).SetupWithoutStarting();using var uiSession=new ProjectSession();uiSession.NewProject("MCP interface",new DateTime(2026,10,19));var owner=new PlannerWindow(uiSession,Path.Combine(output,"views.json"));owner.Show();Pump();
  foreach(var mode in new[]{"Light","Dark"}){owner.SetThemeMode(mode);var panel=new McpConnectorsWindow(new McpSettingsStore(Path.Combine(output,"ui-"+mode+".json")),new McpCredentialStore(),uiSession,owner.RefreshForValidation);panel.Show(owner);Pump();Click(panel,"Add Demo");Assert(panel.GetVisualDescendants().OfType<ListBox>().Any(l=>l.Items.Count==1),"Demo setup available in "+mode);using(var frame=panel.CaptureRenderedFrame()??throw new Exception("No panel frame"))frame.Save(Path.Combine(output,"connectors-"+mode+".png"));Click(panel,"Add Server");Pump();var editor=panel.OwnedWindows.OfType<McpServerEditor>().Single();Click(editor,"Save Server");Assert(editor.IsVisible,"Invalid server stays in editor "+mode);using(var frame=editor.CaptureRenderedFrame()??throw new Exception("No editor frame"))frame.Save(Path.Combine(output,"server-editor-"+mode+".png"));Click(editor,"Cancel");WaitUntil(()=>!panel.OwnedWindows.Any());Click(panel,"Edit Server");WaitUntil(()=>panel.OwnedWindows.OfType<McpServerEditor>().Any());var editing=panel.OwnedWindows.OfType<McpServerEditor>().Single();editing.GetVisualDescendants().OfType<TextBox>().Single(t=>t.Name=="ServerName").Text="Edited demo";Click(editing,"Save Server");WaitUntil(()=>!panel.OwnedWindows.Any());Assert(panel.GetVisualDescendants().OfType<ListBox>().Any(l=>l.Items.OfType<McpServerDefinition>().Any(s=>s.Name=="Edited demo")),"Server edit persists in UI "+mode);Click(panel,"Connect");WaitUntil(()=>panel.GetVisualDescendants().OfType<ListBox>().Any(l=>l.Items.Count==2));var tools=panel.GetVisualDescendants().OfType<ListBox>().Single(l=>l.Items.Count==2);tools.SelectedItem=tools.Items.OfType<McpToolInfo>().Single(t=>t.Name=="example_tasks");Pump();Click(panel,"Review and Run");WaitUntil(()=>panel.OwnedWindows.OfType<McpReviewWindow>().Any());var review=panel.OwnedWindows.OfType<McpReviewWindow>().Single();using(var frame=review.CaptureRenderedFrame()??throw new Exception("No review frame"))frame.Save(Path.Combine(output,"tool-review-"+mode+".png"));Click(review,"Run Tool");WaitUntil(()=>panel.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.Text?.StartsWith("Tool returned.")==true));Assert(uiSession.Tasks.Count==0,"UI tool call requires separate import "+mode);Click(panel,"Import Selected Tasks");WaitUntil(()=>panel.OwnedWindows.OfType<McpTaskImportWindow>().Any());var preview=panel.OwnedWindows.OfType<McpTaskImportWindow>().Single();preview.GetVisualDescendants().OfType<CheckBox>().First().IsChecked=false;Click(preview,"Import Tasks");WaitUntil(()=>uiSession.Tasks.Count==2);Assert(uiSession.Tasks.All(t=>t.Start.HasValue&&t.Finish.HasValue),"UI import calculates dates "+mode);uiSession.Undo();owner.RefreshForValidation();Assert(uiSession.Tasks.Count==0,"UI import is one Undo "+mode);panel.Close();WaitUntil(()=>!panel.IsVisible);Assert(!panel.IsVisible,"Connected panel closes cleanly "+mode);}
  var import=new McpTaskImportWindow([new("Example A","2d","","","0",""),new("Example B","1d","","","0","")],"MCP interface");var importResult=import.ShowDialog<IReadOnlyList<McpImportedTask>?>(owner);Pump();import.GetVisualDescendants().OfType<CheckBox>().First().IsChecked=false;Click(import,"Import Tasks");Assert(importResult.GetAwaiter().GetResult()?.Single().Name=="Example B","Import dialog respects selected rows");owner.CloseForValidation();
  File.WriteAllText(Path.Combine(output,"results.json"),JsonSerializer.Serialize(new{passed=checks.Count,checks},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS: {checks.Count} MCP checks.");return 0;
 }
 private static void WaitUntil(Func<bool> predicate){var clock=System.Diagnostics.Stopwatch.StartNew();while(!predicate()){Pump();Thread.Sleep(10);if(clock.Elapsed>TimeSpan.FromSeconds(20))throw new TimeoutException("UI action did not finish.");}Pump();}
 private static void Pump(){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();Dispatcher.UIThread.RunJobs();}
 private static void Click(Window w,string text){w.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,text)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 private sealed class FixtureHttp:HttpMessageHandler {
  public bool Authorized,Slow;
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){if(Slow)await Task.Delay(Timeout.Infinite,token);Authorized|=request.Headers.Authorization?.ToString()=="Bearer fixture-token";if(request.Method==HttpMethod.Delete)return new(HttpStatusCode.OK);using var input=JsonDocument.Parse(await request.Content!.ReadAsStringAsync(token));var root=input.RootElement;if(!root.TryGetProperty("id",out var id))return new(HttpStatusCode.Accepted);string method=root.GetProperty("method").GetString()!;object result=method switch{"initialize"=>new{protocolVersion="2025-11-25",capabilities=new{tools=new{}},serverInfo=new{name="HTTP fixture",version="1.0"}},"tools/list"=>new{tools=new[]{new{name="echo",description="Fixture",inputSchema=new{type="object",properties=new{message=new{type="string"}}}}}},"tools/call"=>new{content=new[]{new{type="text",text="fixture result"}}},_=>new{}};return new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{jsonrpc="2.0",id=id.Clone(),result}),Encoding.UTF8,"application/json")};}
 }
}
